// The test set for sorting sites (tests/sites-eval.test.ts, scripts/eval-sites.ts): real sites with page
// titles as browsers show them, and the right answer for each.
//   B = for breaks (watching, listening, games, sport, social feeds, gossip)
//   W = for work, study, tasks, shopping, banking
//   M = both (Reddit, news): its pages must stay with your work, so "work" and "mixed" are both right.
// Every other site goes to "dev" (used to tune) or "test" (kept apart, to report accuracy honestly).

export type Truth = 'B' | 'W' | 'M';
export interface EvalSite { site: string; truth: Truth; titles: string[]; set: 'dev' | 'test' }

