export const SITES: EvalSite[] = RAW.map(([site, truth, ...titles], i) => ({ site, truth, titles, set: i % 2 ? 'test' : 'dev' }));

/** A tab for a page on the site, as a browser would report it. */
export function evalUrl(site: string, n: number): string {
  const [host, ...rest] = site.split('/');
  return `https://${host}/${rest.length ? rest.join('/') + '/' : ''}page-${n}`;
}
